package main
import ("context"; "os"; "os/signal"; "beacon-shutdown-manager/internal/app"; "beacon-shutdown-manager/internal/lifecycle")
func main() {
    ctx, cancel := signal.NotifyContext(context.Background(), os.Interrupt)
    defer cancel()
    worker := app.NewWorker()
    lifecycle.Await(ctx, app.StopHook(worker))
}

