package app
import "context"
type Worker struct { Pending int }
func NewWorker() *Worker { return &Worker{Pending: 0} }
func (w *Worker) FlushAndClose(ctx context.Context) {
    select { case <-ctx.Done(): return; default: w.Pending = 0 }
}
func (w *Worker) Abort() { w.Pending = -1 }
